/* PrepperPapa: the app's own text translator (generated by forditas.py from the app source,
   do not edit by hand). */
function ppNyelv(){ return document.documentElement.getAttribute('lang') || 'hu'; }
const PP_FORD_EREDETI = new WeakMap();
let ppFordFut = false;
// ============================================================================
// A FORDITO HATARA -- EGY MONDAT, HAROM ELES ESET (2026-08-26, Thomas kerte, hogy ITT alljon)
// ============================================================================
//
//   A FORDITO A SAJAT DOKUMENTUMANAK SZoVEGCSOMOPONTJAIT JARJA.
//   AMI NEM AZ, AZ NEMA MARAD.
//
// Ez NEM harom kulon hiba volt, hanem EGY hatar, harom helyen:
//  1. KULON ABLAK -- a nyomtatott veszkartya (`cardNyomtat`) `window.open` + `document.write`.
//     A bejaro a SAJAT dokumentumat jarja, az uj ablakot soha nem eri el. Ott epiteskor kell
//     forditani (`ppForditSzoveg(...)` a string-osszefuzesben). Javitva: v40.9.
//  2. UGYANEZ, MASIK LAPON -- a nyomtatott csomaglista (`ppPackBekot`). Ugyanaz a minta,
//     meg nyitva: `256b1ebf` kartya.
//  3. ATTRIBUTUM -- a `placeholder`, `title`, `aria-label` nem szovegcsomopont. Ezt a lenti
//     kulon ciklus kezeli; a hiany 2026-08-26-ig NEM a mechanizmus volt, hanem 25 hianyzo
//     szotar-kulcs. (Az `alt` szandekosan nincs a listan: egyetlen ilyen ertek van, a `Gira`,
//     az pedig termeknev -- nem fordul.)
//
// A NEGYEDIK ESET, HA JON, valoszinuleg megint valami, ami nem szovegcsomopont: `<canvas>`-ra
// rajzolt felirat, letoltott fajl neve, `document.title`, egy `Notification` szovege, vagy egy
// `alert()`. **A kerdes mindig ugyanaz: a felhasznalo OLVASSA-E, es szovegcsomopont-e.**
// A ketto nem ugyanaz, es a kulonbseg csendes -- nem hibauzenetet ad, hanem magyar szoveget
// egy idegen nyelvu feluleten.
function ppSzovegForditas(gyoker) {
  const ny = ppNyelv();
  const sz = (ny === 'hu') ? null : (window.PP_FORD_SZOTAR || {})[ny];
  if (ny !== 'hu' && !sz) return;          // a szotar meg tolt -- majd a betoltes ujra hiv
  ppFordFut = true;                        // a sajat irasainkra ne inditsunk ujabb kort
  try {
    const w = document.createTreeWalker(gyoker || document.body, NodeFilter.SHOW_TEXT);
    let cs;
    while ((cs = w.nextNode())) {
      const p = cs.parentElement;
      // AZ SVG-BEN IS VAN FELIRAT, ES EDDIG KIHAGYTAM (Thomas merese, 2026-08-23 21:5x).
      // A sugo-korut RAJZAI es a tajolo nap-ive `<text>` elemekbe irjak a feliratot
      // ("Adás indítása", "delelés 12:38"). Az `svg` kizarasa ezeket egyben ejtette --
      // es mert a rajzokat a lap INDULASKOR epiti fel (a szotar betoltese ELoTT), az
      // iras-kozbeni forditas sem er el hozzajuk. A `<style>` es a `<script>` marad kizarva.
      if (!p || p.closest('script, style')) continue;
      // A TUDASTAR TARTALMA NEM FELULET (Fonok kepernyokepe, 2026-08-24 06:10).
      // A kepen a "03 EGESZSEGUGY" tema tizennyolc magyar cikkcime kozott EGY angolul
      // allt: "Health". Nem hiba volt, hanem TULTELJESITES -- az "Egeszsegugy" cikkcim
      // veletlenul egyezett egy felulet-szotar kulccsal, es a fordito lecserelte.
      // A tudastar sajat nyelvi retegbol jon (`kb/en/`, Istvan forditasa, kapuval);
      // amig az a kapu csukva, a tartalomnak MAGYARUL kell allnia -- egeszben, nem
      // foltokban. Egy veletlen szotar-egyezes miatt kiszinezett cim rosszabb, mint a
      // kovetkezetes magyar: ugy nez ki, mintha a forditas felig kesz lenne.
      // Ami ITT MARAD forditando: a keret (a "Tudastar" fejlec, a keresomezo, a
      // hibauzenetek, a "Betoltes...", a feloldo-kartya) -- azok felulet.
      if (p.closest('.kbc-c, .kbtitle, .kt, .kc, .kb2, .kbtorzs, .bibjegyzet-elem, .bibjegyzet-forras, .bibtalalat, .biberedeti-forma, .biberedeti-hu, .biberedeti-sor > span + span, .biberedeti-szotar p')) continue;
      const eredeti = PP_FORD_EREDETI.has(cs) ? PP_FORD_EREDETI.get(cs) : cs.textContent;
      const kulcs = eredeti.replace(/\s+/g, ' ').trim();
      if (!kulcs) continue;
      // LANGUAGE NAMES ARE AUTONYMS (owner report 2026-10-30): a language-list entry (an <option> or a data-nyelv button
      // built from PP_NYELVEK) stays in its own language -- "Magyar" was turned into "Hungarian" / "Угорська".
      if (PP_NYELVEK[(p.tagName === 'OPTION' ? p.value : p.dataset && p.dataset.nyelv) || ''] === kulcs) continue;
      if (ny === 'hu') {
        if (PP_FORD_EREDETI.has(cs)) { cs.textContent = eredeti; PP_FORD_EREDETI.delete(cs); }
        continue;
      }
      // A DEMO-ADAT SZoTARA IS IDE TARTOZIK (Fonok, 2026-08-23 20:19: "a teszt adatok
      // meg tovabbra is magyarul vannak"). A `PP_DEMO_EN` eddig CSAK a demo-adat
      // ELoALLITASAKOR futott le (`ppDemoForditas`), tehat aki magyarul toltotte be a
      // teszt-keszletet, annak angolul is magyar nevek alltak a listaban -- a nyelvvaltas
      // a mar meglevo SORAIT nem erintette. Itt viszont a KEPERNYoN allo szoveget
      // forditjuk, tehat a mar bevitt tetelekre is all.
      // A sorrend szandekos: a felulet-szotar eros, a demo-szotar csak kiegeszit.
      // 2026-10-19 (v43.312): a demo-adat minden nyelven a sajat szotarabol (PP_DEMO_NY); a nevek elsobbseget kapnak
      // a felulet-szotarral szemben (ott "Test-Papa" allt, Agnes 08-22-i kerese szerint a "Teszt" nem latszhat).
      const demoNy = (typeof PP_DEMO_NY === 'object' && PP_DEMO_NY[ny]) || {};
      let uj = (window.PP_DEMO_ELSO && PP_DEMO_ELSO.has(kulcs) && demoNy[kulcs]) || sz[kulcs] || demoNy[kulcs]
        || (ny === 'en' && typeof PP_DEMO_EN === 'object' ? PP_DEMO_EN[kulcs] : null);
      // AMI SZAMOT TARTALMAZ, AZ NEM LEHET SZOTAR-KULCS ("3 fő · 7 nap"). Ezekre MINTA
      // kell, kulonben minden lehetseges szam-parhoz kulon sort kellene irni -- vagyis
      // sosem lenne kesz. A mintak a szotar-fajlban allnak, a kodban csak a futtatasuk.
      if (!uj && ny !== 'hu') {
        const mintak = (window.PP_FORD_MINTAK || {})[ny] || [];
        for (const m of mintak) {
          if (!m.minta.test(kulcs)) continue;
          // A KIFOGOTT RESZ IS FORDULHAT (Fonok kepernyokepe a veszkartyakrol, 2026-08-23
          // 20:5x: "vercsoport hianyzik · allergia: Gluten, Szoja, Penicillin"). A minta
          // csak a KERETET forditja le; az allergia-nevek a kifogott csoportban allnak,
          // vesszovel elvalasztva. Ezert minden csoportot atengedunk a szotaron -- tetelenkent
          // is --, es ami nincs benne, az valtozatlanul megy tovabb (nev, szam, sajat szoveg).
          uj = kulcs.replace(m.minta, (...db) => {
            const csoportok = db.slice(1, -2);
            const forditott = csoportok.map((g) => {
              if (typeof g !== 'string' || !g) return g;
              if (sz[g]) return sz[g];
              const tetelek = g.split(/,\s*/);
              if (tetelek.length > 1) return tetelek.map((t) => sz[t] || t).join(', ');
              return g;
            });
            // A `csere` LEHET FuGGVENY IS (2026-09-02 20:2x, Istvan kerte, es o merte ki, miert).
            //
            // MIERT KELLETT: a szam-egyeztetesnel a szam-OSZTALY (1 / 2-4 / 5+) eddig a REGEXBEN
            // allt. Egy szamra ez mukodik, **ketto viszont szorzodik**: a `(\d+) fo · (\d+) nap`
            // alaku mintaknal 3x3 = 9 kulon bejegyzes kellene nyelvenkent. Istvan megszamolta:
            // **kb. 330 kezzel irt sztring het nyelven** -- fuggveny-ertekkel 105, es olvashato.
            //
            // A SZIGNATURA SZANDEKOSAN AZONOS A NATIV `String.replace`-EVEL: (match, p1, p2, ...).
            // A masik hivasi hely (a `ppForditSzoveg`-ben) natv `replace`-t hasznal, ami fuggvenyt
            // amugy is elfogad -- **ha itt mas alakot adnank at, ugyanaz a minta a ket helyen
            // maskepp viselkedne, es ezt semmi nem jelezne.**
            //
            // AMI A KET HELY KoZoTT IGY IS KuLoNBoZIK, es ez NEM uj: itt a csoportok mar
            // ATMENTEK a szotaron (`forditott`), ott nyersek. Szamoknal ez kozombos -- szam
            // nincs a szotarban --, de szoveges csoportnal szamit.
            return (typeof m.csere === 'function')
              ? m.csere(db[0], ...forditott)
              : m.csere.replace(/\$(\d)/g, (_, i) => forditott[Number(i) - 1] ?? '');
          });
          break;
        }
      }
      // AMIT NEM TUDTUNK LEFORDITANI, AZT oSSZEGYuJTJuK (Fonok, 2026-08-23 20:35: "nekem
      // kell bongesznem itt a magyar szavak utan"). Nem o a mero: a lap mostantol maga
      // mondja meg, mibe futott bele. A `window.PP_FORD_HIANY` a bejarasi szkriptbol
      // (`scripts/pp-i18n-hiany.mjs`) kiolvashato -- igy a munkalista ATTOL fugg, ami
      // TENYLEGESEN megjelenik, nem attol, amit a forrasbol kitalalunk.
      if (!uj) {
        if (/[őűáéíóöúüŐŰÁÉÍÓÖÚÜ]/.test(kulcs)) {
          (window.PP_FORD_HIANY || (window.PP_FORD_HIANY = {}))[kulcs] =
            (window.PP_FORD_HIANY[kulcs] || 0) + 1;
        }
        continue;
      }
      if (!PP_FORD_EREDETI.has(cs)) PP_FORD_EREDETI.set(cs, cs.textContent);
      // A KoRuLoLEo SZOKoZT MEGTARTJUK: a `<span>` es a szomszed szoveg kozott gyakran
      // egyetlen szokoz all, es ha azt elvesszuk, az angol szoveg osszeragad.
      //
      // A KULCS NORMALIZALT, A CSOMOPONT SZoVEGE NEM -- ES EZ ELSoRE MEGHARAPOTT.
      // A tobbsoros bekezdesekben a nyers szovegben SORTOReS es tobbszoros szokoz all,
      // a kulcsban viszont egyetlen szokoz; ilyenkor a `replace(kulcs, uj)` NEM TALAL
      // semmit, es CSENDBEN nem csinal semmit. A meres pontosan ezt mutatta: a hosszu
      // bekezdesek magyarul maradtak, holott a szotarban ott alltak. Ha nincs szo szerinti
      // egyezes, a TELJES csomopontot csereljuk, a koruloleo szokozt megtartva.
      if (eredeti.indexOf(kulcs) >= 0) {
        cs.textContent = eredeti.replace(kulcs, uj);
      } else {
        cs.textContent = (eredeti.match(/^\s*/) || [''])[0] + uj + (eredeti.match(/\s*$/) || [''])[0];
      }
    }

    // AZ ATTRIBUTUMOK IS LATSZANAK (Fonok kepernyokepe, 2026-08-23 20:20: az angol lapon
    // a beviteli mezoben "a szoba kodja" allt). A `placeholder`, a `title` es az
    // `aria-label` NEM szoveg-csomopont, tehat a fenti bejaras SOSEM erte el oket --
    // Istvan merese szerint 62 ilyen hely van. A hangfelolvaso csak az `aria-label`-t
    // mondja ki, tehat ott a hiany nem is latszik, csak hallatszik.
    const ATTRIBUTUMOK = ['placeholder', 'title', 'aria-label'];
    const elemek = (gyoker || document.body).querySelectorAll('[placeholder], [title], [aria-label]');
    for (const e of elemek) {
      for (const a of ATTRIBUTUMOK) {
        if (!e.hasAttribute(a)) continue;
        const tarolo = 'ppFordEredeti_' + a.replace('-', '');
        const eredetiErtek = (e.dataset[tarolo] != null) ? e.dataset[tarolo] : e.getAttribute(a);
        const k = String(eredetiErtek).replace(/\s+/g, ' ').trim();
        if (!k) continue;
        if (ny === 'hu') {
          if (e.dataset[tarolo] != null) { e.setAttribute(a, e.dataset[tarolo]); delete e.dataset[tarolo]; }
          continue;
        }
        const demoNy2 = (typeof PP_DEMO_NY === 'object' && PP_DEMO_NY[ny]) || {};
        const forditas = (window.PP_DEMO_ELSO && PP_DEMO_ELSO.has(k) && demoNy2[k]) || sz[k] || demoNy2[k] || (ny === 'en' && typeof PP_DEMO_EN === 'object' ? PP_DEMO_EN[k] : null);
        if (!forditas) continue;
        if (e.dataset[tarolo] == null) e.dataset[tarolo] = eredetiErtek;
        e.setAttribute(a, forditas);
      }
    }
  } finally { ppFordFut = false; }
  // Ha a bejaras KoZBEN valtozott a lap, azonnal megyunk egy kort ra (lasd a figyelot).
  if (ppFordUjraKell) { ppFordUjraKell = false; setTimeout(() => ppSzovegForditas(), 60); }
}

// AMI MENET KoZBEN KELETKEZIK, AZT IS LE KELL FORDITANI. A lista-kirajzolok (keszlet,
// haztartas, tudastar) `innerHTML`-lel dolgoznak, tehat a forditas utan keletkezo
// szoveg magyarul allna ott. Egy figyelo olcsobb, mint minden rajzolo fuggvenyt
// megkeresni es kiegesziteni -- es nem lehet kifelejteni belole egyet sem.
// FORDITAS IRAS KoZBEN -- a FOLYAMATOSAN FRISSuLo helyekre (2026-08-23, Thomas lelete).
//
// A DOM-bejaro utolag javit: megkeresi a magyar szoveget es kicsereli. Ez mindenre jo, AMIT
// egyszer kiirnak -- de a tajolo statusz-sorat a sajat ciklusa MASODPERCENKENT ujrairja, tehat
// a bejaras utan azonnal visszaall magyarra. Ott nem utolag kell javitani, hanem AZ IRAS
// PILLANATABAN forditani. Ugyanaz a szotar es ugyanazok a mintak, csak elobb.
function ppForditSzoveg(sz) {
  const ny = ppNyelv();
  if (ny === 'hu' || typeof sz !== 'string' || !sz) return sz;
  const d = (window.PP_FORD_SZOTAR || {})[ny] || {};
  const kulcs = sz.replace(/\s+/g, ' ').trim();
  if (d[kulcs]) return d[kulcs];
  for (const m of ((window.PP_FORD_MINTAK || {})[ny] || [])) {
    if (m.minta.test(kulcs)) return kulcs.replace(m.minta, m.csere);
  }
  return sz;
}
// TEMPLATE WITH NAMED SLOTS (2026-10-29, Agnes: Hungarian sentences in the EN pack list, compass, SOS card).
// The dictionary key is the Hungarian sentence with {slot} markers, so a number or a name inside the sentence
// no longer breaks the key; the slots are filled AFTER the lookup, in every language (Hungarian too).
// Slot values go in as given: the caller escapes them when the result is used as HTML.
function ppForditKitolt(sz, o) {
  return ppForditSzoveg(sz).replace(/\{(\w+)\}/g, (_, k) => (o && o[k] != null) ? String(o[k]) : '');
}
let ppFordTimer = null, ppFordElsoJel = 0, ppFordUjraKell = false;
function ppFordFigyeloIndit() {
  if (window.__ppFordFigyelo) return;
  window.__ppFordFigyelo = new MutationObserver(() => {
    if (ppNyelv() === 'hu') return;
    // A SAJAT FUTASUNK ALATT ERKEZo VALTOZAST NEM SZABAD ELDOBNI (2026-08-23, merve).
    // Az elso valtozatom itt egyszeruen kilepett, ha epp mi irtunk -- csakhogy a lap
    // KoZBEN is ir (a tajolo statusz-sora epp a bejarasunk alatt cserelodott ki), es
    // az a szoveg onnantol SENKIHEZ nem jutott el: uj mutacio nem jott ra, tehat
    // ujabb kor sem indult. Egy elveszett ertesites itt vegleges magyar szoveget jelent.
    if (ppFordFut) { ppFordUjraKell = true; return; }
    // KIEHEZTETES: A PUSZTA KESLELTETES NEM ELEG (Thomas merese, 2026-08-23 20:51, es
    // visszamerve). Az elso valtozatom minden mutaciora ujraindította a 120 ms-os idozitot.
    // A tajolo kepernyo viszont FOLYAMATOSAN ir (iranyszog, ido, legnyomas), tehat a
    // szamlalo sosem jart le, es a fordito EGYSZER SEM futott le azon a lapon -- a szoveg
    // magyarul maradt, HOLOTT a szotarban ott allt.
    //
    // ES EZ A SAJAT MEREsEMET IS MEGTEVESZTETTE: a hiany-gyujto a forditon BELuL all, tehat
    // amit a fordito SOSEM ert el, az a hiany-listan sem jelent meg. A lap "1 hianyt"
    // jelentett, kozben egy egesz kepernyo magyarul allt. **Egy mero, ami a javitando
    // gepezet belsejeben ul, nem latja azt, ami el sem indult.**
    const most = Date.now();
    if (!ppFordElsoJel) ppFordElsoJel = most;
    clearTimeout(ppFordTimer);
    // 600 ms utan MINDENKEPP lefut, akkor is, ha kozben tovabb valtozik a lap.
    const varakozas = (most - ppFordElsoJel >= 600) ? 0 : 120;
    ppFordTimer = setTimeout(() => { ppFordElsoJel = 0; ppSzovegForditas(); }, varakozas);
  });
  window.__ppFordFigyelo.observe(document.body, { childList: true, subtree: true, characterData: true });
}


// attributes people read (placeholder, aria-label, title) drawn by the calculators' own code
function ppAttrForditas(){ var ny=ppNyelv(), sz=(window.PP_FORD_SZOTAR||{})[ny]; if(!sz) return;
  document.querySelectorAll('.ppkalk [placeholder],.ppkalk [aria-label],.ppkalk [title],.ppkalk optgroup[label]').forEach(function(e){
    ['placeholder','aria-label','title','label'].forEach(function(a){ var v=e.getAttribute(a); if(!v) return;
      var k=v.replace(/\s+/g,' ').trim(); if(sz[k]) e.setAttribute(a, sz[k]); }); }); }
(function(){ var t=null; function fut(){ try{ ppSzovegForditas(); ppAttrForditas(); }catch(e){} }
  function indit(){ fut(); ppFordFigyeloIndit();
    new MutationObserver(function(){ clearTimeout(t); t=setTimeout(ppAttrForditas,150); })
      .observe(document.body,{childList:true,subtree:true}); }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',indit); else indit(); })();
